  "el-berlin": { seq:["Intro","Hypnotic loop","Subtle evolution","Outro"], dec:{en:"Strip techno to a relentless, hypnotic, functional loop.",uk:"Будувати форму через мінімальну, індустріальну, просторову естетику."}, his:{en:"Berlin techno (Tresor, Berghain), 1990s–.",uk:"Берлінське техно (1990-ті — тепер) — звук покинутих заводів."}, works:["Jeff Mills «The Bells»","Ben Klock «Subzero»","Surgeon recordings"], rel:["el-detroit","el-hard","el-minimal"] },
