  "el-industrial": { seq:["Noise intro","Distorted kick loop","Texture shift"], dec:{en:"Fuse techno's pulse with industrial noise and distortion.",uk:"Будувати музику з шуму, металу та ритму машин."}, his:{en:"Industrial techno (Berghain-adjacent), 2010s.",uk:"Індастріал (1970–80-ті) — анти-музика як форма."}, works:["Ancient Methods tracks","Perc «Wax Apple»","Blawan «Why They Hide Their Bodies»"], rel:["el-hard","el-berlin","el-breakcore"] },
